import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, CircleGeometry, PointLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-collection-stat-tile';

  const content = new Group();
  content.name = 'stat-tile-content';
  root.add(content);

  const disposables = [];
  const gsapTimelines = [];

  // --- depth plane 1: machined base plate (surface) ---
  const baseGeo = new BoxGeometry(1.8, 1.2, 0.05);
  const baseMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.65,
    metalness: 0.3,
    clearcoat: 0.1,
  });
  const basePlate = new Mesh(baseGeo, baseMat);
  basePlate.position.set(0, 0, -0.06);
  content.add(basePlate);
  disposables.push(baseGeo, baseMat);

  // --- depth plane 2: machined-metal card body (ink) ---
  const cardGeo = new BoxGeometry(1.5, 0.9, 0.12);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });
  if ('anisotropy' in cardMat) {
    cardMat.anisotropy = 0.5;
    cardMat.anisotropyRotation = Math.PI * 0.25;
  }
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0.02);
  content.add(card);
  disposables.push(cardGeo, cardMat);

  // --- engraved inlay plate (paper) — neutral surface where a value/label would sit ---
  const inlayGeo = new BoxGeometry(1.1, 0.55, 0.015);
  const inlayMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.7,
    metalness: 0.05,
    clearcoat: 0.05,
  });
  const inlay = new Mesh(inlayGeo, inlayMat);
  inlay.position.set(-0.08, 0.05, 0.085);
  content.add(inlay);
  disposables.push(inlayGeo, inlayMat);

  // --- accent signal strip (single brightest element, <=10% of frame) ---
  const accentGeo = new BoxGeometry(1.1, 0.06, 0.02);
  const accentMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.6,
    roughness: 0.4,
    metalness: 0.3,
  });
  const accentStrip = new Mesh(accentGeo, accentMat);
  accentStrip.position.set(-0.08, -0.32, 0.09);
  content.add(accentStrip);
  disposables.push(accentGeo, accentMat);

  // --- text content (bridging idiom — render ONLY spec-provided copy) ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (!item?.text) continue;
    const isLabel = item.role === 'caption' || item.role === 'label';
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? (isLabel ? 24 : 60),
      color: isLabel ? colors.paper : colors.paper,
      align: 'left',
    });
    textObj.position.set(-0.55, isLabel ? -0.18 : 0.05, 0.1);
    content.add(textObj);
    textNodes.push(textObj);
  }

  // --- accent rim light, node-local only (scene supplies ambient 0.6 + key 1.2) ---
  const rimLight = new PointLight(new Color(colors.accent), 0.9, 3.5, 2);
  rimLight.position.set(0.7, 0.55, 0.6);
  content.add(rimLight);

  // --- contact shadow (grounded object) ---
  const shadowGeo = new CircleGeometry(1.35, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.45,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.62, -0.02);
  content.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // --- decorative gear GLB: machined-surface motif, depth plane 3 (foreground accent) ---
  let gearRoot = null;
  let gearDisposed = false;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (gearDisposed) return;
      gearRoot = gltf.scene;
      gearRoot.scale.setScalar(0.28);
      gearRoot.position.set(0.58, 0.28, 0.14);
      content.add(gearRoot);

      const gearTl = gsap.timeline({ repeat: -1 });
      gearTl.to(gearRoot.rotation, {
        z: `+=${Math.PI * 2}`,
        duration: 24,
        ease: 'none',
      });
      gsapTimelines.push(gearTl);
    }).catch(() => {});
  }

  // --- entrance: weighted-settle ---
  content.scale.setScalar(0.9);
  const entranceTl = gsap.timeline();
  entranceTl.to(content.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.6,
    ease: 'power3.out',
  }).to(content.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  gsapTimelines.push(entranceTl);

  // --- cinematic primitives (exactly as specified) ---
  const primitiveHandles = [];
  const primitivesConfig = config.cinematicPrimitives ?? [];
  for (const prim of primitivesConfig) {
    const applyFn = ctx.primitives[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(root, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // --- interaction handlers ---
  const baseY = content.position.y;
  let hoverTl = null;

  const onPointerEnter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(content.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power2.out',
    });
    hoverTl.to(accentMat, {
      emissiveIntensity: 2.1,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  };

  const onPointerLeave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(content.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    });
    hoverTl.to(accentMat, {
      emissiveIntensity: 1.6,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  };

  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(content.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    }).to(content.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.3,
      ease: 'power2.out',
    });
    gsapTimelines.push(pressTl);
    ctx.emit('hub-collection.select', { id: config.id ?? 'hub-collection-stat' });
  };

  root.userData.handlers = {
    onPointerEnter,
    onPointerOver: onPointerEnter,
    onPointerLeave,
    onPointerOut: onPointerLeave,
    onClick,
  };

  root.userData.cleanup = () => {
    gearDisposed = true;
    for (const tl of gsapTimelines) tl.kill();
    if (hoverTl) hoverTl.kill();
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') handle.cleanup();
    }
    for (const item of disposables) {
      if (item && typeof item.dispose === 'function') item.dispose();
    }
    for (const t of textNodes) {
      if (t?.userData?.cleanup) t.userData.cleanup();
    }
    rimLight.dispose?.();
    if (gearRoot) {
      gearRoot.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          for (const m of mats) {
            for (const key in m) {
              if (m[key]?.isTexture) m[key].dispose();
            }
            m.dispose();
          }
        }
      });
    }
  };

  return root;
}
